{"success": true, "content": "def normalize(s):
    if not s:
        return ''
    return s.strip().lower()

def test_basic():
    assert normalize('  Hello  ') == 'hello'

def test_empty():
    assert normalize('') == ''

def test_whitespace_only():
    assert normalize('   ') == ''
    assert normalize('\t\n ') == ''

def test_none():
    assert normalize(None) == ''

def test_unicode():
    assert normalize('  Café  ') == 'café'
    assert normalize('  MÜNCHEN  ') == 'münchen'
    assert normalize('  école  ') == 'école'
    assert normalize('ñññ') == 'ñññ'

def test_very_large_input():
    large = '  X  ' * 100000
    result = normalize(large)
    assert result == ('x  ' * 100000).strip().lower()
    assert len(result) == 500000", "lines": 29, "total_lines": 29, "file_path": "D:\codex-local\data\eval\workspace\E33_existing_test.py"}

